package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.*;import net.minecraft.nbt.CompoundTag;import java.util.*;
/** Existing SBW small-shell movement/damage, one swept direct hit, no explosion or terrain mutation. */
public class AdcShell extends com.atsuishio.superbwarfare.entity.projectile.SmallCannonShellEntity{
 private static final Map<ServerLevel,Set<UUID>>ACTIVE=new WeakHashMap<>();private static final boolean MOVE=moveHook();private static boolean moveHook(){try{com.atsuishio.superbwarfare.entity.projectile.FastThrowableProjectile.class.getDeclaredMethod("projectileMove",Level.class);return true;}catch(NoSuchMethodException e){return false;}}
 private final Set<UUID>whitelist=new HashSet<>();public void whitelist(Set<UUID> values){whitelist.clear();whitelist.addAll(values);}
 private UUID sourceId,ownerId;private String name="";private boolean done,tracked;public AdcShell(EntityType<? extends AdcShell>t,Level l){super(t,l);setLife(70);setDamage(18);setExplosionDamage(0);setExplosionRadius(0);setNoGravity(true);}public void principal(UUID id,String n){ownerId=id;name=n;}public void source(UUID id){sourceId=id;}public boolean from(AdcBlockEntity b){return b!=null&&sourceId!=null&&sourceId.equals(b.id)&&tickCount<4;}public float getCustomGravity(){return 0;}public static int active(ServerLevel l){return ACTIVE.getOrDefault(l,Set.of()).size();}
 @Override public void tick(){if(!MOVE&&sweep(level()))return;super.tick();}
 public void track(){if(!tracked&&level() instanceof ServerLevel l){tracked=true;ACTIVE.computeIfAbsent(l,k->new HashSet<>()).add(getUUID());}}
 private boolean protectedTarget(ServerLevel level,Entity entity){if(sourceId!=null){var site=DefenseData.get(level).site(sourceId);if(site!=null&&level.hasChunkAt(site.root)&&level.getBlockEntity(site.root)instanceof AdcBlockEntity cannon&&sourceId.equals(cannon.id))return AdcTargets.protectedBy(cannon.whitelist.keySet(),level,entity);}return AdcTargets.protectedBy(whitelist,level,entity);}
 private boolean sweep(Level level){if(done){if(!level.isClientSide)discard();return true;}if(!(level instanceof ServerLevel l))return false;if(!tracked){tracked=true;ACTIVE.computeIfAbsent(l,k->new HashSet<>()).add(getUUID());}Vec3 a=position(),b=a.add(getDeltaMovement());if(!Hgd01Lasers.loaded(l,a,b)){discard();return true;}var wall=l.clip(new net.minecraft.world.level.ClipContext(a,b,net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,this));Vec3 end=wall.getType()==HitResult.Type.MISS?b:wall.getLocation();Entity best=null;double fraction=2;for(var e:l.getEntities(this,new AABB(a,end).inflate(.7),v->!protectedTarget(l,v)&&AdcTargets.hostile(l,ownerId,name,v,42))){var hit=e.getBoundingBox().inflate(.25).clip(a,end);if(hit.isPresent()){double t=a.distanceToSqr(hit.get());if(t<fraction||best==null){fraction=t;best=e;}}}if(best!=null){hit(best,end);return true;}if(wall.getType()!=HitResult.Type.MISS){finish(end);return true;}return false;}
 private void hit(Entity target,Vec3 at){if(level().isClientSide||done||protectedTarget((ServerLevel)level(),target)||!AdcTargets.hostile((ServerLevel)level(),ownerId,name,target,42))return;done=true;com.atsuishio.superbwarfare.tools.DamageHandlerKt.forceHurt(target,com.atsuishio.superbwarfare.init.ModDamageTypes.causeProjectileHitDamage(level().registryAccess(),this,getOwner()),getDamageValue());effect(at);discard();}
 private void effect(Vec3 at){if(level() instanceof ServerLevel l&&AdcConfig.EFFECTS.get()>0)l.sendParticles(net.minecraft.core.particles.ParticleTypes.CRIT,at.x,at.y,at.z,AdcConfig.EFFECTS.get()*2,.1,.1,.1,.03);}
 private void finish(Vec3 at){if(level().isClientSide||done)return;done=true;effect(at);discard();}
 @Override public void onHitEntity(EntityHitResult h){hit(h.getEntity(),h.getLocation());if(!done)finish(h.getLocation());}@Override public void onHitBlock(BlockHitResult h){finish(h.getLocation());}public void afterHitEntity(EntityHitResult h){onHitEntity(h);}public void afterHitBlock(BlockHitResult h){onHitBlock(h);}public void performDamage(Entity e,float amount,boolean headshot){hit(e,e.getBoundingBox().getCenter());}@Override public void destroyBlock(BlockHitResult h){}@Override public void causeExplode(Vec3 p){finish(p);}@Override public boolean forceLoadChunk(){return false;}
 @Override public void remove(RemovalReason r){if(level() instanceof ServerLevel l){var set=ACTIVE.get(l);if(set!=null){set.remove(getUUID());if(set.isEmpty())ACTIVE.remove(l);}}super.remove(r);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(ownerId!=null)n.putUUID("ADCPrincipal",ownerId);if(sourceId!=null)n.putUUID("ADCSource",sourceId);var friends=new net.minecraft.nbt.ListTag();for(var who:whitelist)friends.add(net.minecraft.nbt.StringTag.valueOf(who.toString()));n.put("ADCWhitelist",friends);n.putString("ADCName",name);n.putBoolean("ADCDone",done);}@Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);ownerId=n.hasUUID("ADCPrincipal")?n.getUUID("ADCPrincipal"):null;sourceId=n.hasUUID("ADCSource")?n.getUUID("ADCSource"):null;whitelist.clear();for(var entry:n.getList("ADCWhitelist",8))try{whitelist.add(UUID.fromString(entry.getAsString()));}catch(IllegalArgumentException ignored){}name=n.getString("ADCName");done=n.getBoolean("ADCDone");}
}
